const std = @import("std");
const helpers = @import("json_helpers.zig");
const CerebrasClient = @import("cerebras_client.zig").CerebrasClient;
const ModalClient = @import("modal_client.zig").ModalClient;
const DragonflyPool = @import("dragonfly_client.zig").DragonflyPool;
const Router = @import("router.zig").Router;
const SearchRequest = @import("router.zig").SearchRequest;
const KdbLogger = @import("kdb_logger.zig").KdbLogger;
const Allocator = std.mem.Allocator;

const Stats = struct {
    requests_total: std.atomic.Value(u64) = std.atomic.Value(u64).init(0),
    searches_total: std.atomic.Value(u64) = std.atomic.Value(u64).init(0),
};

fn logJson(level: []const u8, msg: []const u8, fields: anytype) void {
    var gpa = std.heap.page_allocator;
    var out = std.ArrayList(u8).init(gpa);
    defer out.deinit();
    const ts = helpers.nowMillis();
    out.writer().print("{{\"ts\":{d},\"level\":\"{s}\",\"msg\":\"{s}\"", .{ ts, level, msg }) catch return;
    inline for (@typeInfo(@TypeOf(fields)).@"struct".fields) |f| {
        const v = @field(fields, f.name);
        out.writer().print(",\"{s}\":", .{f.name}) catch return;
        switch (@typeInfo(@TypeOf(v))) {
            .Pointer => out.writer().print("\"{s}\"", .{v}) catch return,
            .Int, .ComptimeInt => out.writer().print("{d}", .{v}) catch return,
            .Float, .ComptimeFloat => out.writer().print("{d}", .{v}) catch return,
            .Bool => out.writer().print("{}", .{v}) catch return,
            else => out.writer().print("\"{any}\"", .{v}) catch return,
        }
    }
    out.writer().writeAll("}\n") catch return;
    std.debug.print("{s}", .{out.items});
}

fn writeSse(w: anytype, data: []const u8) !void {
    try w.writeAll("data: ");
    try w.writeAll(data);
    try w.writeAll("\n\n");
    try w.flush();
}

fn readJsonBody(allocator: Allocator, req: *std.http.Server.Request) ![]u8 {
    const max = 1 << 20;
    return try req.reader().readAllAlloc(allocator, max);
}

pub fn main() !void {
    var gpa_impl = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa_impl.deinit();
    const allocator = gpa_impl.allocator();
    const host = try helpers.getEnvDefault(allocator, "GATEWAY_HOST", "0.0.0.0");
    defer allocator.free(host);
    const port: u16 = @intCast(helpers.getEnvIntDefault("GATEWAY_PORT", 8080));
    const cerebras_base = try helpers.getEnvDefault(allocator, "CEREBRAS_BASE_URL", "");
    defer allocator.free(cerebras_base);
    const cerebras_key = try helpers.getEnv(allocator, "CEREBRAS_API_KEY");
    defer allocator.free(cerebras_key);
    const cerebras_timeout: u32 = @intCast(helpers.getEnvIntDefault("CEREBRAS_REQUEST_TIMEOUT_MS", 30000));
    const cerebras_retries: u8 = @intCast(helpers.getEnvIntDefault("CEREBRAS_MAX_RETRIES", 4));
    const modal_embed = try helpers.getEnv(allocator, "MODAL_EMBEDDING_URL");
    defer allocator.free(modal_embed);
    const modal_search = try helpers.getEnv(allocator, "MODAL_VECTORSEARCH_URL");
    defer allocator.free(modal_search);
    const modal_graph = try helpers.getEnvDefault(allocator, "MODAL_GRAPH_URL", modal_search);
    defer allocator.free(modal_graph);
    const modal_timeout: u32 = @intCast(helpers.getEnvIntDefault("MODAL_REQUEST_TIMEOUT_MS", 60000));
    const modal_retries: u8 = @intCast(helpers.getEnvIntDefault("MODAL_MAX_RETRIES", 4));
    const df_url = try helpers.getEnv(allocator, "DRAGONFLY_URL");
    defer allocator.free(df_url);
    const pool_size: usize = @intCast(helpers.getEnvIntDefault("DRAGONFLY_POOL_SIZE", 16));
    const kdb_host = try helpers.getEnvDefault(allocator, "KDB_HOST", "127.0.0.1");
    defer allocator.free(kdb_host);
    const kdb_port: u16 = @intCast(helpers.getEnvIntDefault("KDB_PORT", 5001));

    var df_host: []const u8 = "127.0.0.1";
    var df_port: u16 = 6379;
    if (std.mem.startsWith(u8, df_url, "redis://")) {
        const rest = df_url["redis://".len..];
        const colon = std.mem.indexOfScalar(u8, rest, ':') orelse rest.len;
        df_host = rest[0..colon];
        if (colon < rest.len) {
            df_port = std.fmt.parseInt(u16, rest[colon + 1 ..], 10) catch 6379;
        }
    }

    var cerebras = CerebrasClient.init(allocator, cerebras_base, cerebras_key, cerebras_timeout, cerebras_retries);
    var modal = ModalClient.init(allocator, modal_embed, modal_search, modal_graph, modal_timeout, modal_retries);
    var cache = try DragonflyPool.init(allocator, df_host, df_port, pool_size);
    defer cache.deinit();
    var router = Router.init(allocator, &cerebras, &modal, &cache);
    var kdb = KdbLogger.init(allocator, kdb_host, kdb_port);
    defer kdb.deinit();
    var stats = Stats{};

    const address = try std.net.Address.parseIp(host, port);
    var server = std.http.Server.init(allocator, .{ .reuse_address = true });
    defer server.deinit();
    try server.listen(address);
    logJson("info", "gateway_listening", .{ .host = host, .port = port });

    var running = true;
    var sig = try std.posix.sigaction(std.posix.SIG.INT, &.{ .handler = .{ .handler = handleSig }, .mask = std.posix.empty_sigset, .flags = 0 }, null);
    _ = sig;
    _ = try std.posix.sigaction(std.posix.SIG.TERM, &.{ .handler = .{ .handler = handleSig }, .mask = std.posix.empty_sigset, .flags = 0 }, null);
    global_running_ptr = &running;

    while (running) {
        var res = server.accept(.{ .allocator = allocator }) catch |e| {
            logJson("error", "accept_failed", .{ .err = @errorName(e) });
            continue;
        };
        defer res.deinit();
        const start_ms = helpers.nowMillis();
        stats.requests_total.fetchAdd(1, .monotonic);
        handleRequest(allocator, &router, &kdb, &stats, &res.request) catch |e| {
            logJson("error", "request_failed", .{ .err = @errorName(e) });
            res.request.respond(.{ .status = .internal_server_error, .body = "internal_error" }) catch {};
        };
        const dt = helpers.nowMillis() - start_ms;
        _ = dt;
        kdb.flush();
    }
}

var global_running_ptr: ?*bool = null;

fn handleSig(sig: c_int) callconv(.C) void {
    _ = sig;
    if (global_running_ptr) |p| p.* = false;
}

fn handleRequest(allocator: Allocator, router: *Router, kdb: *KdbLogger, stats: *Stats, req: *std.http.Server.Request) !void {
    const method = req.method;
    const target = req.target;
    const req_id = std.crypto.random.int(u64);
    logJson("info", "http_request", .{ .id = req_id, .method = @tagName(method), .path = target });

    if (std.mem.eql(u8, target, "/health")) {
        const body = "{\"status\":\"ok\"}";
        try req.respond(.{ .status = .ok, .extra_headers = &.{.{ .name = "Content-Type", .value = "application/json" }}, .body = body });
        return;
    }

    if (std.mem.eql(u8, target, "/stats")) {
        var buf = std.ArrayList(u8).init(allocator);
        defer buf.deinit();
        try buf.writer().print("{{\"requests_total\":{d},\"searches_total\":{d}}}", .{
            stats.requests_total.load(.monotonic),
            stats.searches_total.load(.monotonic),
        });
        try req.respond(.{ .status = .ok, .extra_headers = &.{.{ .name = "Content-Type", .value = "application/json" }}, .body = buf.items });
        return;
    }

    if (std.mem.eql(u8, target, "/search") and method == .POST) {
        stats.searches_total.fetchAdd(1, .monotonic);
        const body = try readJsonBody(allocator, req);
        defer allocator.free(body);
        var tree = try std.json.parseFromSlice(std.json.Value, allocator, body, .{});
        defer tree.deinit();
        const obj = tree.value.object;
        const q = obj.get("query") orelse return error.BadRequest;
        var sr: SearchRequest = .{ .query = q.string };
        if (obj.get("deep_research")) |v| sr.deep_research = v.bool;
        if (obj.get("disable_reasoning")) |v| sr.disable_reasoning = v.bool;
        if (obj.get("clear_thinking")) |v| sr.clear_thinking = v.bool;

        try req.respondStreaming(.{
            .status = .ok,
            .extra_headers = &.{
                .{ .name = "Content-Type", .value = "text/event-stream" },
                .{ .name = "Cache-Control", .value = "no-cache" },
                .{ .name = "Connection", .value = "keep-alive" },
            },
        });

        const writer = req.writer();
        const req_ts = helpers.nowMillis();
        const complex = Router.isComplex(sr);
        var event_buf = std.ArrayList(u8).init(allocator);
        defer event_buf.deinit();

        const start_ev = try helpers.jsonStringify(allocator, .{ .type = "search_start", .id = req_id, .ts = req_ts, .complex = complex });
        defer allocator.free(start_ev);
        try kdb.enqueue(start_ev);

        try router.route(sr, struct {
            w: @TypeOf(writer),
            allocator: Allocator,
            req_id: u64,
            kdb: *KdbLogger,

            pub fn call(self: @This(), token: []const u8) !void {
                try writeSse(self.w, token);
                const ev = try helpers.jsonStringify(self.allocator, .{ .type = "search_token", .id = self.req_id, .ts = helpers.nowMillis(), .n = token.len });
                defer self.allocator.free(ev);
                try self.kdb.enqueue(ev);
            }
        }{ .w = writer, .allocator = allocator, .req_id = req_id, .kdb = kdb }.call, struct {
            w: @TypeOf(writer),
            allocator: Allocator,
            req_id: u64,
            kdb: *KdbLogger,

            pub fn call(self: @This()) !void {
                try writeSse(self.w, "[DONE]");
                const ev = try helpers.jsonStringify(self.allocator, .{ .type = "search_done", .id = self.req_id, .ts = helpers.nowMillis() });
                defer self.allocator.free(ev);
                try self.kdb.enqueue(ev);
            }
        }{ .w = writer, .allocator = allocator, .req_id = req_id, .kdb = kdb }.call);
        return;
    }

    try req.respond(.{ .status = .not_found, .body = "not_found" });
}
