const std = @import("std");
const helpers = @import("json_helpers.zig");

pub const ModalClient = struct {
    allocator: std.mem.Allocator,
    embedding_url: []const u8,
    search_url: []const u8,
    graph_url: []const u8,
    timeout_ms: u32,
    max_retries: u8,

    pub fn init(allocator: std.mem.Allocator, embedding_url: []const u8, search_url: []const u8, graph_url: []const u8, timeout_ms: u32, max_retries: u8) ModalClient {
        return .{
            .allocator = allocator,
            .embedding_url = embedding_url,
            .search_url = search_url,
            .graph_url = graph_url,
            .timeout_ms = timeout_ms,
            .max_retries = max_retries,
        };
    }

    fn sleepBackoff(attempt: u8) void {
        const base: u64 = 200;
        const pow = @as(u64, 1) << @intCast(@min(attempt, 6));
        const jitter = @as(u64, std.crypto.random.int(u16)) % 80;
        std.time.sleep((base * pow + jitter) * std.time.ns_per_ms);
    }

    fn postJson(self: *ModalClient, url: []const u8, payload_json: []const u8) ![]u8 {
        var attempt: u8 = 0;
        while (true) : (attempt += 1) {
            var client = std.http.Client{ .allocator = self.allocator };
            defer client.deinit();
            client.connection_pool = .{ .idle_timeout_ms = 10_000, .max_idle = 16 };

            var headers = std.http.Headers{ .allocator = self.allocator };
            defer headers.deinit();
            try headers.append("Content-Type", "application/json");

            var req = client.open(.POST, try std.Uri.parse(url), headers, .{ .allocator = self.allocator }) catch |e| {
                if (attempt >= self.max_retries) return e;
                sleepBackoff(attempt);
                continue;
            };
            defer req.deinit();
            req.read_timeout_ms = self.timeout_ms;
            req.write_timeout_ms = self.timeout_ms;

            try req.send();
            try req.writeAll(payload_json);
            try req.finish();
            try req.wait();

            if (req.response.status.class() != .success) {
                const body = try req.reader().readAllAlloc(self.allocator, 1 << 20);
                defer self.allocator.free(body);
                if (attempt >= self.max_retries) return error.ModalHTTP;
                sleepBackoff(attempt);
                continue;
            }
            return try req.reader().readAllAlloc(self.allocator, 1 << 22);
        }
    }

    pub fn encode(self: *ModalClient, text: []const u8) ![]u8 {
        const payload = try helpers.jsonStringify(self.allocator, .{ .text = text });
        defer self.allocator.free(payload);
        return try self.postJson(self.embedding_url, payload);
    }

    pub fn search(self: *ModalClient, embedding_json: []const u8, k: u32) ![]u8 {
        const payload = try helpers.jsonStringify(self.allocator, .{ .embedding = embedding_json, .k = k });
        defer self.allocator.free(payload);
        return try self.postJson(self.search_url, payload);
    }

    pub fn graph(self: *ModalClient, nodes_json: []const u8) ![]u8 {
        const payload = try helpers.jsonStringify(self.allocator, .{ .nodes = nodes_json });
        defer self.allocator.free(payload);
        return try self.postJson(self.graph_url, payload);
    }
};
