pub fn sha256Hex(allocator: std.mem.Allocator, data: []const u8) ![]u8 {
    var h = std.crypto.hash.sha2.Sha256.init(.{});
    h.update(data);
    var digest: [32]u8 = undefined;
    h.final(&digest);

    var out = try allocator.alloc(u8, 64);
    for (digest, 0..) |b, i| {
        _ = try std.fmt.bufPrint(out[i * 2 .. i * 2 + 2], "{x:0>2}", .{b});
    }
    return out;
