const std = @import("std");
const CerebrasClient = @import("cerebras_client.zig").CerebrasClient;
const ModalClient = @import("modal_client.zig").ModalClient;
const DragonflyPool = @import("dragonfly_client.zig").DragonflyPool;
const sha = @import("sha256.zig");
const helpers = @import("json_helpers.zig");

pub const SearchRequest = struct {
    query: []const u8,
    deep_research: ?bool = null,
    disable_reasoning: ?bool = null,
    clear_thinking: ?bool = null,
};

pub const RoutedModel = enum { Summarizer, Reasoning };

pub const Router = struct {
    allocator: std.mem.Allocator,
    cerebras: *CerebrasClient,
    modal: *ModalClient,
    cache: *DragonflyPool,

    pub fn init(allocator: std.mem.Allocator, cerebras: *CerebrasClient, modal: *ModalClient, cache: *DragonflyPool) Router {
        return .{ .allocator = allocator, .cerebras = cerebras, .modal = modal, .cache = cache };
    }

    pub fn isComplex(req: SearchRequest) bool {
        if (req.deep_research orelse false) return true;
        if (req.query.len > 200) return true;
        const q = std.ascii.lowerStringAlloc(std.heap.page_allocator, req.query) catch return false;
        defer std.heap.page_allocator.free(q);
        const keys = [_][]const u8{ "compare", " vs ", "implement", "code", "analyze", "explain deeply" };
        for (keys) |k| if (std.mem.indexOf(u8, q, k) != null) return true;
        return false;
    }

    pub fn cacheKey(self: *Router, req: SearchRequest) ![]u8 {
        var buf = std.ArrayList(u8).init(self.allocator);
        defer buf.deinit();
        try buf.appendSlice(req.query);
        try buf.appendSlice("|dr=");
        try buf.appendSlice(if ((req.deep_research orelse false)) "1" else "0");
        try buf.appendSlice("|disr=");
        try buf.appendSlice(if ((req.disable_reasoning orelse false)) "1" else "0");
        try buf.appendSlice("|ct=");
        try buf.appendSlice(if ((req.clear_thinking orelse false)) "1" else "0");
        const hex = try sha.sha256Hex(self.allocator, buf.items);
        return hex;
    }

    pub const RagDoc = struct { id: i64, score: f32, title: []const u8, url: []const u8, text: []const u8 };

    fn parseModalResults(self: *Router, json_bytes: []const u8) ![]RagDoc {
        var tree = try std.json.parseFromSlice(std.json.Value, self.allocator, json_bytes, .{});
        defer tree.deinit();
        const root = tree.value;
        const results_v = root.object.get("results") orelse return error.BadModal;
        const arr = results_v.array.items;
        var out = try self.allocator.alloc(RagDoc, arr.len);
        errdefer self.allocator.free(out);
        var i: usize = 0;
        while (i < out.len) : (i += 1) {
            const o = arr[i].object;
            const title_str = o.get("title").?.string;
            const url_str = o.get("url").?.string;
            const text_str = o.get("text").?.string;
            out[i] = .{
                .id = @intCast(o.get("id").?.integer),
                .score = @floatCast(o.get("score").?.float),
                .title = try self.allocator.dupe(u8, title_str),
                .url = try self.allocator.dupe(u8, url_str),
                .text = try self.allocator.dupe(u8, text_str),
            };
        }
        return out;
    }

    fn qwenFilter(self: *Router, query: []const u8, docs: []const RagDoc) ![]i64 {
        var list = std.ArrayList(u8).init(self.allocator);
        defer list.deinit();
        for (docs) |d| {
            try list.writer().print("{d}: {s}\n", .{ d.id, d.title });
        }

        const prompt = try std.fmt.allocPrint(self.allocator, "You are a retrieval filter. Given a user query and candidate documents, output a JSON array of 3 to 5 document IDs (numbers only) that are most relevant. No extra text.\n\nQuery:\n{s}\n\nCandidates:\n{s}\n", .{ query, list.items });
        defer self.allocator.free(prompt);
        const msgs = [_]CerebrasClient.ChatMessage{
            .{ .role = "system", .content = "Return only JSON." },
            .{ .role = "user", .content = prompt },
        };
        const resp = try self.cerebras.chatOnce(.{
            .model = "qwen-3-235b-a22b-instruct-2507",
            .stream = false,
            .temperature = 0.1,
            .max_completion_tokens = 256,
            .messages = &msgs,
        });
        defer self.allocator.free(resp);

        var tree = try std.json.parseFromSlice(std.json.Value, self.allocator, resp, .{});
        defer tree.deinit();
        const content = tree.value.object.get("choices").?.array.items[0].object.get("message").?.object.get("content").?.string;

        var id_tree = try std.json.parseFromSlice(std.json.Value, self.allocator, content, .{});
        defer id_tree.deinit();
        const items = id_tree.value.array.items;
        const n = @min(items.len, 5);
        var ids = try self.allocator.alloc(i64, n);
        for (ids, 0..) |*dst, idx| dst.* = @intCast(items[idx].integer);
        return ids;
    }

    fn buildRagContext(self: *Router, docs: []const RagDoc, selected_ids: []const i64, max_chars: usize) ![]u8 {
        var map = std.AutoHashMap(i64, RagDoc).init(self.allocator);
        defer map.deinit();
        for (docs) |d| try map.put(d.id, d);
        var out = std.ArrayList(u8).init(self.allocator);
        errdefer out.deinit();
        for (selected_ids) |id| {
            if (map.get(id)) |d| {
                try out.writer().print("### Doc {d}\nTitle: {s}\nURL: {s}\nScore: {d:.4}\n\n{s}\n\n", .{ d.id, d.title, d.url, d.score, d.text });
                if (out.items.len >= max_chars) break;
            }
        }
        if (out.items.len > max_chars) out.shrinkRetainingCapacity(max_chars);
        return out.toOwnedSlice();
    }

    pub fn route(self: *Router, req: SearchRequest, on_token: anytype, on_done: anytype) !void {
        const complex = isComplex(req);
        const ttl: u32 = if (complex) 6 * 3600 else 3600;
        const key_hex = try self.cacheKey(req);
        defer self.allocator.free(key_hex);
        const cache_key = try std.fmt.allocPrint(self.allocator, "rag:{s}", .{key_hex});
        defer self.allocator.free(cache_key);

        if (try self.cache.get(cache_key)) |cached| {
            defer self.allocator.free(cached);
            try on_token(cached);
            try on_done();
            return;
        }

        const embed = try self.modal.encode(req.query);
        defer self.allocator.free(embed);
        const search = try self.modal.search(embed, 12);
        defer self.allocator.free(search);
        const docs = try self.parseModalResults(search);
        defer {
            for (docs) |d| {
                self.allocator.free(d.title);
                self.allocator.free(d.url);
                self.allocator.free(d.text);
            }
            self.allocator.free(docs);
        }

        const selected = try self.qwenFilter(req.query, docs);
        defer self.allocator.free(selected);
        const ctx = try self.buildRagContext(docs, selected, 40_000);
        defer self.allocator.free(ctx);

        const model = if (complex) "zai-glm-4.7" else "gpt-oss-120b";
        const sys = "You are a concise but precise neural search engine. Use the provided context as grounding. If a claim is not supported by context, say so. Provide links when available.";
        const user_prompt = try std.fmt.allocPrint(self.allocator, "User query:\n{s}\n\nContext:\n{s}\n\nAnswer:", .{ req.query, ctx });
        defer self.allocator.free(user_prompt);
        const msgs = [_]CerebrasClient.ChatMessage{
            .{ .role = "system", .content = sys },
            .{ .role = "user", .content = user_prompt },
        };

        var full_acc = std.ArrayList(u8).init(self.allocator);
        errdefer full_acc.deinit();

        try self.cerebras.chatStream(.{
            .model = model,
            .stream = true,
            .temperature = if (complex) 0.35 else 0.3,
            .max_completion_tokens = if (complex) 40_000 else 8_000,
            .messages = &msgs,
            .disable_reasoning = req.disable_reasoning,
            .clear_thinking = req.clear_thinking,
        }, struct {
            allocator: std.mem.Allocator,
            acc: *std.ArrayList(u8),
            on_token: @TypeOf(on_token),

            pub fn call(self_: @This(), token: []const u8) !void {
                try self_.acc.appendSlice(token);
                try self_.on_token(token);
            }
        }{ .allocator = self.allocator, .acc = &full_acc, .on_token = on_token }.call);

        const final = try full_acc.toOwnedSlice();
        defer self.allocator.free(final);
        try self.cache.setEx(cache_key, ttl, final);
        try on_done();
    }
};

