const std = @import("std");

pub const RedisValueTag = enum { Null, SimpleString, BlobString, Number, Array, Map, Error };

pub const RedisValue = union(RedisValueTag) {
    Null: void,
    SimpleString: []u8,
    BlobString: []u8,
    Number: i64,
    Array: []RedisValue,
    Map: []RedisMapEntry,
    Error: []u8,
};

pub const RedisMapEntry = struct { key: RedisValue, value: RedisValue };

pub const RedisClient = struct {
    allocator: std.mem.Allocator,
    stream: std.net.Stream,
    reader: std.io.BufferedReader(4096, std.net.Stream.Reader),
    writer: std.net.Stream.Writer,

    pub fn connect(allocator: std.mem.Allocator, host: []const u8, port: u16) !RedisClient {
        const addr = try std.net.Address.resolveIp(host, port);
        const s = try std.net.tcpConnectToAddress(addr);
        var br = std.io.bufferedReader(s.reader());
        var w = s.writer();
        var c: RedisClient = .{ .allocator = allocator, .stream = s, .reader = br, .writer = w };
        try c.sendCmd(&.{ "HELLO", "3" });
        _ = try c.readValue();
        return c;
    }

    pub fn close(self: *RedisClient) void {
        self.stream.close();
    }

    fn writeBulk(self: *RedisClient, s: []const u8) !void {
        try self.writer.print("${d}\r\n", .{s.len});
        try self.writer.writeAll(s);
        try self.writer.writeAll("\r\n");
    }

    pub fn sendCmd(self: *RedisClient, parts: []const []const u8) !void {
        try self.writer.print("*{d}\r\n", .{parts.len});
        for (parts) |p| try self.writeBulk(p);
    }

    fn readLine(self: *RedisClient, allocator: std.mem.Allocator) ![]u8 {
        var line = std.ArrayList(u8).init(allocator);
        errdefer line.deinit();
        while (true) {
            const b = try self.reader.reader().readByte();
            if (b == '\r') {
                const lf = try self.reader.reader().readByte();
                if (lf != '\n') return error.Protocol;
                break;
            }
            try line.append(b);
        }
        return line.toOwnedSlice();
    }

    fn readN(self: *RedisClient, allocator: std.mem.Allocator, n: usize) ![]u8 {
        var buf = try allocator.alloc(u8, n);
        errdefer allocator.free(buf);
        try self.reader.reader().readNoEof(buf);
        const cr = try self.reader.reader().readByte();
        const lf = try self.reader.reader().readByte();
        if (cr != '\r' or lf != '\n') return error.Protocol;
        return buf;
    }

    pub fn readValue(self: *RedisClient) !RedisValue {
        const prefix = try self.reader.reader().readByte();
        return switch (prefix) {
            '_' => blk: {
                _ = try self.readLine(self.allocator);
                break :blk RedisValue{ .Null = {} };
            },
            '+' => blk: {
                const s = try self.readLine(self.allocator);
                break :blk RedisValue{ .SimpleString = s };
            },
            '$' => blk: {
                const len_line = try self.readLine(self.allocator);
                defer self.allocator.free(len_line);
                const n = try std.fmt.parseInt(i64, len_line, 10);
                if (n < 0) break :blk RedisValue{ .Null = {} };
                const s = try self.readN(self.allocator, @intCast(n));
                break :blk RedisValue{ .BlobString = s };
            },
            ':' => blk: {
                const l = try self.readLine(self.allocator);
                defer self.allocator.free(l);
                const n = try std.fmt.parseInt(i64, l, 10);
                break :blk RedisValue{ .Number = n };
            },
            '*' => blk: {
                const l = try self.readLine(self.allocator);
                defer self.allocator.free(l);
                const n = try std.fmt.parseInt(i64, l, 10);
                if (n < 0) break :blk RedisValue{ .Null = {} };
                var arr = try self.allocator.alloc(RedisValue, @intCast(n));
                var i: usize = 0;
                while (i < arr.len) : (i += 1) arr[i] = try self.readValue();
                break :blk RedisValue{ .Array = arr };
            },
            '%' => blk: {
                const l = try self.readLine(self.allocator);
                defer self.allocator.free(l);
                const n = try std.fmt.parseInt(i64, l, 10);
                if (n < 0) break :blk RedisValue{ .Null = {} };
                var entries = try self.allocator.alloc(RedisMapEntry, @intCast(n));
                var i: usize = 0;
                while (i < entries.len) : (i += 1) {
                    const k = try self.readValue();
                    const v = try self.readValue();
                    entries[i] = .{ .key = k, .value = v };
                }
                break :blk RedisValue{ .Map = entries };
            },
            '-' => blk: {
                const e = try self.readLine(self.allocator);
                break :blk RedisValue{ .Error = e };
            },
            else => error.Protocol,
        };
    }

    pub fn freeValue(self: *RedisClient, v: RedisValue) void {
        switch (v) {
            .Null => {},
            .Number => {},
            .SimpleString => |s| self.allocator.free(s),
            .BlobString => |s| self.allocator.free(s),
            .Error => |s| self.allocator.free(s),
            .Array => |a| {
                for (a) |item| self.freeValue(item);
                self.allocator.free(a);
            },
            .Map => |m| {
                for (m) |e| {
                    self.freeValue(e.key);
                    self.freeValue(e.value);
                }
                self.allocator.free(m);
            },
        }
    }
};

pub const DragonflyPool = struct {
    allocator: std.mem.Allocator,
    host: []const u8,
    port: u16,
    pool_size: usize,
    conns: []RedisClient,
    idx: std.atomic.Value(usize),

    pub fn init(allocator: std.mem.Allocator, host: []const u8, port: u16, pool_size: usize) !DragonflyPool {
        var conns = try allocator.alloc(RedisClient, pool_size);
        var i: usize = 0;
        while (i < pool_size) : (i += 1) {
            conns[i] = try RedisClient.connect(allocator, host, port);
        }
        return .{
            .allocator = allocator,
            .host = host,
            .port = port,
            .pool_size = pool_size,
            .conns = conns,
            .idx = std.atomic.Value(usize).init(0),
        };
    }

    pub fn deinit(self: *DragonflyPool) void {
        for (self.conns) |*c| c.close();
        self.allocator.free(self.conns);
    }

    fn next(self: *DragonflyPool) *RedisClient {
        const i = self.idx.fetchAdd(1, .monotonic);
        return &self.conns[i % self.pool_size];
    }

    pub fn get(self: *DragonflyPool, key: []const u8) !?[]u8 {
        var c = self.next();
        try c.sendCmd(&.{ "GET", key });
        const v = try c.readValue();
        defer c.freeValue(v);
        return switch (v) {
            .Null => null,
            .BlobString => |s| try self.allocator.dupe(u8, s),
            .SimpleString => |s| try self.allocator.dupe(u8, s),
            else => error.Unexpected,
        };
    }

    pub fn setEx(self: *DragonflyPool, key: []const u8, ttl_seconds: u32, value: []const u8) !void {
        var c = self.next();
        var ttl_buf: [32]u8 = undefined;
        const ttl_str = try std.fmt.bufPrint(&ttl_buf, "{d}", .{ttl_seconds});
        try c.sendCmd(&.{ "SET", key, value, "EX", ttl_str });
        const r = try c.readValue();
        defer c.freeValue(r);
        switch (r) {
            .SimpleString => {},
            else => return error.Unexpected,
        }
    }

    pub fn setNx(self: *DragonflyPool, key: []const u8, value: []const u8) !bool {
        var c = self.next();
        try c.sendCmd(&.{ "SET", key, value, "NX" });
        const r = try c.readValue();
        defer c.freeValue(r);
        return switch (r) {
            .Null => false,
            .SimpleString => true,
            else => false,
        };
    }

    pub fn bfAdd(self: *DragonflyPool, filter: []const u8, item: []const u8) !bool {
        var c = self.next();
        try c.sendCmd(&.{ "BF.ADD", filter, item });
        const r = try c.readValue();
        defer c.freeValue(r);
        return switch (r) {
            .Number => |n| n == 1,
            else => false,
        };
    }

    pub fn bfExists(self: *DragonflyPool, filter: []const u8, item: []const u8) !bool {
        var c = self.next();
        try c.sendCmd(&.{ "BF.EXISTS", filter, item });
        const r = try c.readValue();
        defer c.freeValue(r);
        return switch (r) {
            .Number => |n| n == 1,
            else => false,
        };
    }
};
