pub const KdbLogger = struct {
    allocator: std.mem.Allocator,
    host: []const u8,
    port: u16,
    queue: std.fifo.LinearFifo([]u8, .Dynamic),

    pub fn init(allocator: std.mem.Allocator, host: []const u8, port: u16) KdbLogger {
        return .{
            .allocator = allocator,
            .host = host,
            .port = port,
            .queue = std.fifo.LinearFifo([]u8, .Dynamic).init(allocator),
        };
    }

    pub fn deinit(self: *KdbLogger) void {
        while (self.queue.readItem()) |item| self.allocator.free(item);
        self.queue.deinit();
    }

    pub fn enqueue(self: *KdbLogger, json_payload: []const u8) !void {
        const msg = try self.allocator.dupe(u8, json_payload);
        try self.queue.writeItem(msg);
    }

    pub fn flush(self: *KdbLogger) void {
        if (self.queue.count == 0) return;

        var buf = std.ArrayList(u8).init(self.allocator);
        defer buf.deinit();

        while (self.queue.readItem()) |item| {
            buf.appendSlice(item) catch {
                self.allocator.free(item);
                continue;
            };
            buf.append('\n') catch {};
            self.allocator.free(item);
            if (buf.items.len >= 64 * 1024) break;
        }

        var url_buf: [256]u8 = undefined;
        const url = std.fmt.bufPrint(&url_buf, "", .{ self.host, self.port }) catch return;

        var client = std.http.Client{ .allocator = self.allocator };
        defer client.deinit();

        var headers = std.http.Headers{ .allocator = self.allocator };
        defer headers.deinit();
        headers.append("Content-Type", "application/json") catch return;

        var req = client.open(.POST, std.Uri.parse(url) catch return, headers, .{ .allocator = self.allocator }) catch return;
        defer req.deinit();
        req.read_timeout_ms = 1500;
        req.write_timeout_ms = 1500;

        req.send() catch return;
        req.writeAll(buf.items) catch return;
        req.finish() catch return;
        _ = req.wait() catch return;
        const resp_body = req.reader().readAllAlloc(self.allocator, 1 << 20) catch return;
        defer self.allocator.free(resp_body);
    }
};
