const std = @import("std");

pub const SseEvent = struct {
    data: []const u8,
};

pub const SseParser = struct {
    allocator: std.mem.Allocator,
    buf: std.ArrayList(u8),

    pub fn init(allocator: std.mem.Allocator) SseParser {
        return .{ .allocator = allocator, .buf = std.ArrayList(u8).init(allocator) };
    }

    pub fn deinit(self: *SseParser) void {
        self.buf.deinit();
    }

    pub fn feed(self: *SseParser, chunk: []const u8, on_event: anytype) !void {
        try self.buf.appendSlice(chunk);

        while (true) {
            const idx_opt = std.mem.indexOf(u8, self.buf.items, "\n\n");
            if (idx_opt == null) break;
            const idx = idx_opt.?;
            const frame = self.buf.items[0..idx];
            const rest = self.buf.items[idx + 2 ..];
            var tmp = std.ArrayList(u8).init(self.allocator);
            errdefer tmp.deinit();
            try tmp.appendSlice(rest);
            self.buf.deinit();
            self.buf = tmp;

            var it = std.mem.splitScalar(u8, frame, '\n');
            var data_acc = std.ArrayList(u8).init(self.allocator);
            errdefer data_acc.deinit();
            while (it.next()) |line| {
                if (std.mem.startsWith(u8, line, "data:")) {
                    const payload = std.mem.trim(u8, line["data:".len..], " \t\r");
                    if (payload.len > 0) {
                        if (data_acc.items.len > 0) try data_acc.append('\n');
                        try data_acc.appendSlice(payload);
                    }
                }
            }
            const data = try data_acc.toOwnedSlice();
            try on_event(.{ .data = data });
        }
    }
};
