const std = @import("std");
const json = std.json;
const helpers = @import("json_helpers.zig");
const SseParser = @import("stream_parser.zig").SseParser;

pub const CerebrasClient = struct {
    allocator: std.mem.Allocator,
    base_url: []const u8,
    api_key: []const u8,
    timeout_ms: u32,
    max_retries: u8,

    pub fn init(allocator: std.mem.Allocator, base_url: []const u8, api_key: []const u8, timeout_ms: u32, max_retries: u8) CerebrasClient {
        return .{
            .allocator = allocator,
            .base_url = base_url,
            .api_key = api_key,
            .timeout_ms = timeout_ms,
            .max_retries = max_retries,
        };
    }

    fn sleepBackoff(attempt: u8) void {
        const base: u64 = 150;
        const pow = @as(u64, 1) << @intCast(@min(attempt, 6));
        const jitter = @as(u64, std.crypto.random.int(u16)) % 50;
        std.time.sleep((base * pow + jitter) * std.time.ns_per_ms);
    }

    pub const ChatMessage = struct { role: []const u8, content: []const u8 };

    pub const ChatRequest = struct {
        model: []const u8,
        stream: bool,
        temperature: f32,
        max_completion_tokens: u32,
        messages: []const ChatMessage,
        disable_reasoning: ?bool = null,
        clear_thinking: ?bool = null,
    };

    pub fn chatOnce(self: *CerebrasClient, req: ChatRequest) ![]u8 {
        return try self.chatInternal(req, null);
    }

    pub fn chatStream(self: *CerebrasClient, req: ChatRequest, on_token: anytype) !void {
        _ = try self.chatInternal(req, on_token);
    }

    fn chatInternal(self: *CerebrasClient, req: ChatRequest, on_token: anytype) ![]u8 {
        var url_buf = std.ArrayList(u8).init(self.allocator);
        defer url_buf.deinit();
        try url_buf.appendSlice(self.base_url);
        if (!std.mem.endsWith(u8, self.base_url, "/")) try url_buf.append('/');
        try url_buf.appendSlice("v1/chat/completions");
        const url = url_buf.items;

        const body = try helpers.jsonStringify(self.allocator, req);
        defer self.allocator.free(body);

        var attempt: u8 = 0;
        while (attempt < self.max_retries) : (attempt += 1) {
            var client = std.http.Client{ .allocator = self.allocator };
            defer client.deinit();
            client.connection_pool = .{ .idle_timeout_ms = 10_000, .max_idle = 16 };

            var headers = std.http.Headers{ .allocator = self.allocator };
            defer headers.deinit();
            try headers.append("Content-Type", "application/json");
            var auth_buf: [512]u8 = undefined;
            const auth = try std.fmt.bufPrint(&auth_buf, "Bearer {s}", .{self.api_key});
            try headers.append("Authorization", auth);

            var req_opt = client.open(.POST, try std.Uri.parse(url), headers, .{ .allocator = self.allocator }) catch |e| {
                if (attempt >= self.max_retries - 1) return e;
                sleepBackoff(attempt);
                continue;
            };
            defer req_opt.deinit();

            req_opt.transfer_encoding = .chunked;
            req_opt.read_timeout_ms = self.timeout_ms;
            req_opt.write_timeout_ms = self.timeout_ms;

            try req_opt.send();
            try req_opt.writeAll(body);
            try req_opt.finish();
            try req_opt.wait();

            const status = req_opt.response.status;
            if (status.class() != .success) {
                var err_body = try req_opt.reader().readAllAlloc(self.allocator, 1 << 20);
                defer self.allocator.free(err_body);
                if (attempt >= self.max_retries - 1) return error.CerebrasHTTP;
                sleepBackoff(attempt);
                continue;
            }

            if (req.stream and @TypeOf(on_token) != @TypeOf(null)) {
                var parser = SseParser.init(self.allocator);
                defer parser.deinit();

                var full = std.ArrayList(u8).init(self.allocator);
                errdefer full.deinit();

                var buf: [4096]u8 = undefined;
                while (true) {
                    const n = req_opt.reader().read(&buf) catch |e| {
                        if (e == error.EndOfStream) break;
                        return e;
                    };
                    if (n == 0) break;
                    const chunk = buf[0..n];
                    try full.appendSlice(chunk);
                    try parser.feed(chunk, struct {
                        allocator: std.mem.Allocator,
                        full_text: *std.ArrayList(u8),
                        on_token: @TypeOf(on_token),

                        pub fn call(self_: @This(), ev: SseEvent) !void {
                            defer self_.allocator.free(ev.data);
                            if (std.mem.eql(u8, ev.data, "[DONE]")) return;
                            var tree = try std.json.parseFromSlice(std.json.Value, self_.allocator, ev.data, .{});
                            defer tree.deinit();
                            const root = tree.value;
                            const choices = root.object.get("choices") orelse return;
                            if (choices.array.items.len == 0) return;
                            const delta = choices.array.items[0].object.get("delta") orelse return;
                            const content = delta.object.get("content") orelse return;
                            if (content.string.len == 0) return;
                            try self_.on_token(content.string);
                        }
                    }{ .allocator = self.allocator, .full_text = &full, .on_token = on_token }.call);
                }
                return try full.toOwnedSlice();
            } else {
                const resp_body = try req_opt.reader().readAllAlloc(self.allocator, 1 << 22);
                return resp_body;
            }
        }
        return error.MaxRetriesExceeded;
    }
};
